    internal static class ActionSelectorRules
    {
        internal static Dictionary<string,string> Aliases(string owner,Dictionary<string,JObject> actions)
        {
            var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
            if(JObject.Parse(DeclaredAliases)[owner] is JObject aliases)
                foreach(var alias in aliases.Properties())
                    if(actions.ContainsKey(alias.Value.Value<string>())) result[alias.Name]=alias.Value.Value<string>();
            foreach(var action in actions.Keys) if(!result.ContainsKey(action))result[action]=action;
            if(owner=="UniBridge_ManageGameObject")
            {
                foreach(var alias in new[]{"creategameobject","newgameobject"})result[alias]="create";
                foreach(var alias in new[]{"update","patch","updategameobject"})result[alias]="modify";
                foreach(var alias in new[]{"destroy","removegameobject","deletegameobject"})result[alias]="delete";
                foreach(var alias in new[]{"search","searchgameobjects"})result[alias]="find";
                foreach(var alias in new[]{"listcomponents","inspectcomponents"})result[alias]="get_components";
                result["inspectcomponent"]="get_component";result["deletecomponent"]="remove_component";
                foreach(var alias in new[]{"setcomponentproperties","updatecomponent","patchcomponent"})result[alias]="set_component_property";
            }
            var normalized=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
            foreach(var alias in result)normalized[ActionOutputValidation.Normalize(alias.Key,Normalization(owner,false))]=alias.Value;
            // Keep enum spellings for metadata readers; runtime enum selection
            // uses the actual enum value mapping rather than string coercion.
            foreach(var alias in result)if(!normalized.ContainsKey(alias.Key))normalized[alias.Key]=alias.Value;
            result=normalized;
            return result;
        }
        internal static string LookupPolicy(string owner)
        {
            if(owner=="UniBridge_ManageGameObject")return "gameobject-copy-alias";
            switch(owner)
            {
                case "UniBridge_CaptureView":case "UniBridge_ManageConstraints":case "UniBridge_ManageInputActions":
                case "UniBridge_ManageNavigation":case "UniBridge_ManagePhysics2D":case "UniBridge_ManagePhysics3D":
                case "UniBridge_ManageRendering":case "UniBridge_ManageTilemap2D":case "UniBridge_ManageTimeline":
                case "UniBridge_ManageUIToolkit":return "first-present";
                default:return "skip-null";
            }
        }
        internal static string Normalization(string owner,bool enumSelector)
        {
            if(enumSelector)return "enum-name-case-insensitive";
            if(owner=="UniBridge_ToolGuide")return "guide-underscore";
            if(owner=="UniBridge_Script")return "lower-only";
            if(owner=="UniBridge_ManageAnimatorController" || owner=="UniBridge_ManagePrefab")return "lower-trim";
            switch(owner)
            {
                case "UniBridge_EditorEvents":case "UniBridge_WaitForEvent":case "UniBridge_ExecutionStatus":
                case "UniBridge_WorkSession":case "UniBridge_VersionControl":case "UniBridge_ManageAnimationClip":
                case "UniBridge_Discover":
                case "UniBridge_VisualSceneAudit":
                case "UniBridge_ManageAudio":case "UniBridge_ManageVFX":case "UniBridge_ManageGameObject":
                    return "separators-trim";
                default:return "separators";
            }
        }
